INSERT INTO public.categorias VALUES ('a46b91d4-ddde-4aa7-bc06-e26d6cba7f88', 'bienestar', 'Bienestar emocional', DEFAULT, NULL, '2026-11-06 19:10:20.822059+00', true, false, 10, 'Bienestar', NULL, NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.categorias VALUES ('48c327d0-a72c-4534-a715-b9dc8e44950c', 'diagnostico-doble', 'Diagnóstico doble: transformación digital con factor humano', DEFAULT, NULL, '2026-11-06 19:10:21.900327+00', true, true, 1, 'Diagnóstico doble', 'Transformación digital con factor humano. Le habla a transformación digital, gerencias y líderes, con voz declarativa, en texto y carrusel. Lleva a charla + diagnóstico con Ingen-IA, charlas en eventos de tecnología y coaching.', 'linkedin', false) ON CONFLICT DO NOTHING;
INSERT INTO public.categorias VALUES ('274f840d-9bf5-4e81-8946-e20b5f57ccd6', 'bienestar-e-impacto', 'Bienestar e impacto: lo que le pasa a las personas cuando llega la IA, y cómo medirlo', DEFAULT, NULL, '2026-11-06 19:10:21.900327+00', true, true, 2, 'Bienestar e impacto', 'Lo que le pasa a las personas cuando llega la IA, y cómo medirlo. Le habla a RRHH, bienestar, líderes y academia. Ángulo «Lo que se ve»: lo que RRHH y yo observamos en las personas y los equipos cuando ya usan IA, incluso como apoyo emocional: estrés, desgaste, bienestar. Ángulo «Cómo se mide»: medir el impacto humano y no solo la adopción: indicadores, evaluación de pilotos, instrumentos.', 'linkedin', false) ON CONFLICT DO NOTHING;
INSERT INTO public.categorias VALUES ('9d22cc15-a313-44ae-8b57-9686dea779ba', 'psicologia-en-la-mesa', 'Psicología en la mesa: la psicología donde se construye la IA', DEFAULT, NULL, '2026-11-06 19:10:21.900327+00', true, true, 3, 'Psicología en la mesa', 'La psicología donde se construye la IA; lo digo y lo hago. Le habla a academia, centros de innovación, autoridades, empresas y marcas de tecnología. Ángulo «Lo que planteo»: la IA y la salud mental como tema país y académico: IA ética, datos de salud, regulación y el rol de la psicología en diseñar y evaluar la IA. Ángulo «Lo que construyo»: mi caso a la vista, una psicóloga que construye y entrena modelos: Eureka Engine, Game Over Impostora, videojuegos, el diplomado, Conidolly, mi etapa de psicóloga cyborg.', 'linkedin', false) ON CONFLICT DO NOTHING;
INSERT INTO public.categorias VALUES ('6bb30927-b429-4614-968d-b20df742727e', 'mujeres-lideres', 'Mujeres líderes, IA y síndrome del impostor', DEFAULT, NULL, '2026-11-06 19:10:21.900327+00', true, true, 4, 'Mujeres líderes', 'Mujeres líderes, IA y síndrome del impostor. Le habla a mujeres líderes, agrupaciones STEM y RRHH, con voz íntima, en texto y video. Lleva a coachings y talleres para mujeres líderes y a Game Over Impostora.', 'linkedin', false) ON CONFLICT DO NOTHING;
INSERT INTO public.categorias VALUES ('34309383-6eb1-40ba-b5ec-91e1e61ae1c2', 'game-over-impostora', 'Game Over Impostora', DEFAULT, NULL, '2026-11-06 19:10:21.900327+00', true, true, 1, 'Game Over Impostora', 'Patrones con nombre; la impostora frente a la IA («no soy tecnológica») y frente a emprender; lo que el entorno pone. Serie Game Over / Continue.', 'instagram', false) ON CONFLICT DO NOTHING;
INSERT INTO public.categorias VALUES ('da3d21c4-dced-44b7-9eb3-3a4f7caa3833', 'mi-nueva-partida', 'Mi nueva partida', DEFAULT, NULL, '2026-11-06 19:10:21.900327+00', true, true, 2, 'Mi nueva partida', 'Mi reinvención con IA y la de ella: lo que vivo al aprender, construir y emprender, y cómo usar la IA con criterio para pensar, decidir, ordenar, vender y ganar tiempo. Ángulo «Lo vivo»: mi giro de psicóloga que aprende a entrenar modelos, construye y emprende, con dudas, números y avances. Ángulo «Pruébalo tú»: usar la IA con criterio en su propia reinvención.', 'instagram', false) ON CONFLICT DO NOTHING;
INSERT INTO public.categorias VALUES ('106c5161-a144-4fe2-beba-f1d3037de1e3', 'inteligencia-emocional', 'Inteligencia emocional aplicada: autocuidado, productividad y relaciones', DEFAULT, NULL, '2026-11-06 19:10:21.900327+00', true, true, 3, 'Inteligencia emocional', 'Autocuidado, productividad y relaciones: límites, decir que no, energía, conversaciones difíciles. Serie Ahora que lo ves.', 'instagram', false) ON CONFLICT DO NOTHING;
INSERT INTO public.categorias VALUES ('29ae9e77-1414-4c3c-87d4-a5128b8bc17e', 'capa-tdah', 'Capa TDAH', DEFAULT, NULL, '2026-11-06 19:10:21.900327+00', true, true, 4, 'Capa TDAH', 'Cómo trabaja mi cerebro y qué me sirve, siempre separado de la evidencia. Nivel 2: lo vivo y comparto lo elaborado, sin detalle clínico. Aparece dentro de los otros pilares, en más o menos una de cada seis piezas.', 'instagram', true) ON CONFLICT DO NOTHING;
INSERT INTO public.categorias VALUES ('fc9d27dc-0dc2-4e6e-abca-64ab8a065a08', 'ia-salud-mental', 'IA y salud mental', DEFAULT, NULL, '2026-11-06 19:10:21.379859+00', true, true, 1, 'IA y salud mental', 'Qué dice la evidencia sobre chatbots, apps y modelos: uso real, beneficios y riesgos.', NULL, false) ON CONFLICT DO NOTHING;
