INSERT INTO public.afirmaciones VALUES ('c285b3c4-68fa-4549-bb9a-75124a6c91a1', '3feb0a1a-2614-43d6-84c9-b3c94a0a9002', 'ffe8285a-6b4d-4b30-85ac-51fe9ec4661c', 0, '{}', NULL, 'texto', 'Una de cada cuatro personas consultadas ya usó un chatbot para hablar de su salud mental.', 'consejo', 'estudio', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, '2026-11-08 23:40:55.9347+00') ON CONFLICT DO NOTHING;
INSERT INTO public.pilar_angulos VALUES ('34d9e648-65bb-4ae8-b7af-24122a09ed0c', '274f840d-9bf5-4e81-8946-e20b5f57ccd6', 'linkedin', false, 'como-se-mide', 'Cómo se mide', 'Medir el impacto humano y no solo la adopción: indicadores, evaluación de pilotos, instrumentos. Voz declarativa, carrusel PDF con datos.', 2, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.pilar_angulos VALUES ('20821dab-f942-4ea4-ae62-75e4b7099c4b', '274f840d-9bf5-4e81-8946-e20b5f57ccd6', 'linkedin', false, 'lo-que-se-ve', 'Lo que se ve', 'Lo que RRHH y yo observamos en las personas y los equipos cuando ya usan IA, incluso como apoyo emocional: estrés, desgaste, bienestar. Voz íntima, texto en primera persona.', 1, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.pilar_angulos VALUES ('0b466605-0b68-47cd-b4c8-7e25f8409595', '9d22cc15-a313-44ae-8b57-9686dea779ba', 'linkedin', false, 'lo-que-construyo', 'Lo que construyo', 'Mi caso a la vista. Una psicóloga que construye y entrena modelos: Eureka Engine, Game Over Impostora, videojuegos, el diplomado, Conidolly, mi etapa de psicóloga cyborg. Voz íntima, fotos reales, demos y video.', 2, 0.33333333333333333333) ON CONFLICT DO NOTHING;
INSERT INTO public.pilar_angulos VALUES ('198b89fd-37e1-4669-9385-f73c7209142a', '9d22cc15-a313-44ae-8b57-9686dea779ba', 'linkedin', false, 'lo-que-planteo', 'Lo que planteo', 'La IA y la salud mental como tema país y académico: IA ética, datos de salud, regulación y el rol de la psicología en diseñar y evaluar la IA. Voz declarativa, carrusel con datos y fuentes revisadas.', 1, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.pilar_angulos VALUES ('006928d9-7804-4b6a-b250-29a43032971c', 'da3d21c4-dced-44b7-9eb3-3a4f7caa3833', 'instagram', false, 'pruebalo-tu', 'Pruébalo tú', 'Usar la IA con criterio en su propia reinvención. Reel de pantalla y carrusel paso a paso. Series «Prompt con inteligencia emocional» y «Pequeño experimento».', 2, 0.33333333333333333333) ON CONFLICT DO NOTHING;
INSERT INTO public.pilar_angulos VALUES ('777cd2d3-9845-43fa-b55a-6dbd0e520140', 'da3d21c4-dced-44b7-9eb3-3a4f7caa3833', 'instagram', false, 'lo-vivo', 'Lo vivo', 'Mi giro de psicóloga que aprende a entrenar modelos, construye y emprende, con dudas, números y avances. Reel detrás de escena y Stories, voz íntima. Series «Mi nueva partida» y «Lo probé».', 1, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.teorias VALUES ('994c1586-3baa-44c1-b697-3ea8a0c5c0c3', 'El chatbot llena un hueco de acceso', 'Quien usa IA para su salud mental suele tener problemas de acceso.', NULL, NULL, NULL, 'sintetizando', NULL, NULL, '2026-11-08 23:40:55.929428+00', NULL, NULL, '2026-11-08 23:40:55.929428+00', 'motor', '2026-10-12', '{}', NULL, NULL, 'alto', '[]', NULL) ON CONFLICT DO NOTHING;
