INSERT INTO public.carruseles VALUES ('56f845b7-de2c-4682-b13d-4ceb656db435', 'fd8deefb-953f-43e1-ada9-9fb83ea0dccb', 1, '[{"tipo": "portada", "texto": "Lo que un chatbot no ve de ti"}, {"tipo": "idea", "texto": "Un chatbot te responde a cualquier hora. Eso ayuda, pero no te conoce."}, {"tipo": "idea", "texto": "No nota el silencio largo antes de una respuesta difícil.", "destacado": "silencio"}, {"tipo": "idea", "texto": "No ve cómo cambia tu voz cuando hablas de tu familia.", "destacado": "voz"}, {"tipo": "idea", "texto": "Puede ayudarte a ordenar ideas o a ensayar una conversación difícil.", "destacado": "ordenar"}, {"tipo": "cierre", "texto": "¿En qué momento te sirvió escribirle a una app, y en cuál sentiste que faltaba alguien?", "fuente": "Fuente: Stanford Medicine · AI for Mental Health Symposium (2026)"}]', 'Un chatbot puede acompañarte a las tres de la mañana, cuando no hay nadie más despierto.
